INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca442153cd649cc66f46d31c1e193c24', 'Board', '9', 'Mathematics', 'math_9_statistics', 'Statistics', 'Pie chart representation', '[]', '["percentage","central angle","pie chart","fraction"]', 0, 0, '[]', 'MCQ', NULL, 0, 970, 'CLASS_9_BASIC', 2, 0.0, 'In a class of 40 students, 8 students like football. In a pie chart representing the preferences, what is the central angle (in degrees) of the sector for football?', '["72°", "90°", "108°", "45°"]', '72°', 'Fraction = 8/40 = 0.2. Central angle = 0.2 × 360° = 72°.', '["Step 1: Compute the fraction of students who like football.", "Step 2: Multiply the fraction by 360° to obtain the central angle."]', 'Central angle = \frac{\text{part}}{\text{whole}} \times 360^{\circ}', 'math.statistics.piechart_angle', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:43:55.209Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca46e595d8ca64872dddf738f5beacc3', 'Board', '8', 'Mathematics', 'math_8_algebra_identities', 'Algebraic Expressions and Identities', 'Standard Identities', '[]', '["square of a binomial","expansion","sign rule","identity"]', 0, 0, '[]', 'MCQ', NULL, 0, 770, 'CLASS_8_RECALL', 3, 0.0, 'What is the expanded form of \((a - b)^2\)?', '["a^2 - 2ab + b^2", "a^2 + 2ab + b^2", "a^2 - b^2", "a^2 + b^2"]', 'a^2 - 2ab + b^2', '[Duplicate Quarantined] Using the identity \((a - b)^2 = a^2 - 2ab + b^2\), the middle term is negative because the signs of the two terms are opposite.', '["Step 1: Recall the standard identity for the square of a difference.", "Step 2: Apply the identity: \\((a - b)^2 = a^2 - 2ab + b^2\\).", "Step 3: Verify each option against the derived expression."]', '(a - b)^2 = a^2 - 2ab + b^2', 'math.algebra.square_difference', 'Board Class 8', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:54:25.194Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca4fbc259333b6933d4a26e9e2058c33', 'Board', '10', 'Mathematics', 'math_10_board_polynomials', 'Polynomials', 'Zeros and graphical interpretation', '[]', '["real zeros","graphical method","fundamental theorem of algebra","cubic polynomial"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 3, 0.0, 'The graph of $y = x^{3} - 3x$ cuts the $x$‑axis at three distinct points. How many distinct real zeros does the polynomial have?', '["1", "2", "3", "4"]', '3', 'A real zero corresponds to an $x$‑intercept of the graph. Since the curve meets the $x$‑axis at three points, the polynomial has three distinct real zeros.', '["Step 1: Recognise that a real zero of a polynomial is an $x$‑coordinate where $y=0$.", "Step 2: Observe from the description that the graph intersects the $x$‑axis three times.", "Step 3: Conclude that there are three distinct real zeros."]', '', 'math.algebra.polynomial.real_zeros', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:14:19.161Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca50bda6921de1766c02fff6bfb8c533', 'JEEMains', '11', 'Mathematics', 'math_11_jm_series', 'Sequences and Series', 'Sum of squares of natural numbers', '[]', '["sum_of_squares","natural_numbers","formula_application"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Find the sum of the squares of the first ten natural numbers, i.e., compute $\displaystyle\sum_{k=1}^{10} k^2$.', '["385", "330", "440", "495"]', '385', 'The formula for the sum of squares is $\sum_{k=1}^{n} k^2 = \dfrac{n(n+1)(2n+1)}{6}$. Substituting $n=10$ gives $\dfrac{10\times11\times21}{6}=385$.', '["Step 1: Write the sum‑of‑squares formula $\\frac{n(n+1)(2n+1)}{6}$.", "Step 2: Substitute $n=10$ to obtain $\\frac{10\\times11\\times21}{6}$.", "Step 3: Perform the multiplication and division to get $385$."]', '$\displaystyle\sum_{k=1}^{n} k^2 = \frac{n(n+1)(2n+1)}{6}$', 'math.series.sum_of_squares', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:49:16.156Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca53fa5a7b3d891aa99bf3ffe89c6cc0', 'JEEMains', '12', 'Mathematics', 'math_12_jm_integrals', 'Integrals', 'Definite integral properties symmetry', '[]', '["definite integral","symmetry","trigonometric integral","even function"]', 0, 0, '[]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, 0.0, 'The value of $\int_{-\pi/4}^{\pi/4} \sin^2 x \, dx$ is equal to', '[]', '0.79', 'Use symmetry: $\int_{-a}^{a} \sin^2 x \, dx = 2\int_0^{a} \frac{1 - \cos 2x}{2} dx = 0.79$', '["Step 1: Use $\\sin^2 x = \\frac{1 - \\cos 2x}{2}$", "Step 2: Integrate from 0 to π/4 and double"]', '\int_{-a}^a f(x)dx = 2\int_0^a f(x)dx \text{ if } f \text{ even}', 'math.calculus.symmetry_odd_even_mistake', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:04:30.103Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca59748c8a182a8026d9f9dac3f51210', 'JEEMains', '11', 'Mathematics', 'math_11_jm_trig', 'Trigonometric Functions', 'Heights and distances', '[]', '["tan function","angle of elevation","height calculation","simultaneous equations"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 4, 0.0, 'A tower of unknown height stands on level ground. From a point 50 m from the base, the angle of elevation to the top is $30^{\circ}$. From a point 120 m from the base on the same line, the angle of elevation is $15^{\circ}$. Find the height of the tower (in metres) to the nearest integer.', '[]', '35', 'Let the distance from the first observation point to the tower base be $d$ metres. Then $\tan30^{\circ}=h/d$ and $\tan15^{\circ}=h/(d+70)$. Solving these two equations gives $h=35\,$m.', '["Step 1: Set $d$ as the distance from the first point (50 m) to the tower base; the second point is $d+70$ m away.", "Step 2: Write the two tangent relations: $\\tan30^{\\circ}=h/d$ and $\\tan15^{\\circ}=h/(d+70)$.", "Step 3: Express $d$ from the first equation ($d=h/\\tan30^{\\circ}$) and substitute into the second.", "Step 4: Solve for $h$, obtaining $h=35$ m."]', '$\tan\theta = \frac{\text{opposite}}{\text{adjacent}}$', 'mathematics.trig.distance_height_misinterpret', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:44:35.620Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca5c966d9edf811422e1188063037417', 'NEET', '12', 'Biology', 'bio_12_neet_ecosystem', 'Population growth logistic exponential r K selection', 'Population growth logistic exponential r K selection', '[]', '["Population growth","Logistic exponential growth","Carrying capacity","r K selection"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'NEET_MEDIUM', 6, -1.0, '$$\frac{dP}{dt}=rP\left(1-\frac{P}{K}\right)$$ represents the rate of change of population $P$ with respect to time $t$. If the initial population is $P_0=100$ and the carrying capacity is $K=1000$, what is the time $t$ when the population reaches $P=500$?', '[]', '3.69', 'To solve this differential equation, we can use separation of variables. We separate the variables $P$ and $t$ and integrate both sides. This gives us $$\int \frac{dP}{P\left(1-\frac{P}{K}\right)}=\int rdt.$$We can evaluate the integrals on the left-hand side to get $$-\ln\left(1-\frac{P}{K}\right)=rt+C.$$We can use the initial condition $P_0=100$ to find the value of $C$. Substituting $P=100$ and $t=0$ into the equation, we get $$-\ln\left(1-\frac{100}{K}\right)=C.$$We can solve for $C$ to get $$C=-\ln\left(1-\frac{100}{K}\right).$$Substituting this value of $C$ into the equation, we get $$-\ln\left(1-\frac{P}{K}\right)=rt-\ln\left(1-\frac{100}{K}\right).$$We can simplify this equation to get $$\ln\left(1-\frac{100}{K}\right)-\ln\left(1-\frac{P}{K}\right)=rt.$$We can use the property of logarithms that $\ln a-\ln b=\ln\left(\frac{a}{b}\right)$ to simplify the equation to $$\ln\left(\frac{1-\frac{100}{K}}{1-\frac{P}{K}}\right)=rt.$$We can exponentiate both sides to get $$\frac{1-\frac{100}{K}}{1-\frac{P}{K}}=e^{rt}.$$We can substitute $P=500$ and $K=1000$ into the equation to get $$\frac{1-\frac{100}{1000}}{1-\frac{500}{1000}}=e^{rt}.$$We can simplify the equation to get $$\frac{\frac{900}{1000}}{\frac{500}{1000}}=e^{rt}.$$We can cancel out the denominators to get $$\frac{900}{500}=e^{rt}.$$We can simplify the equation to get $$1.8=e^{rt}.$$We can take the natural logarithm of both sides to get $$\ln 1.8=rt.$$We can substitute $t=3.69$ into the equation to get $$\ln 1.8=r(3.69).$$We can solve for $r$ to get $$r=\frac{\ln 1.8}{3.69}.$$We can substitute this value of $r$ into the equation $$\frac{1-\frac{100}{K}}{1-\frac{P}{K}}=e^{rt}$$ to get $$\frac{1-\frac{100}{1000}}{1-\frac{500}{1000}}=e^{\frac{\ln 1.8}{3.69}t}.$$We can simplify the equation to get $$\frac{\frac{900}{1000}}{\frac{500}{1000}}=e^{\frac{\ln 1.8}{3.69}t}.$$We can cancel out the denominators to get $$\frac{900}{500}=e^{\frac{\ln 1.8}{3.69}t}.$$We can simplify the equation to get $$1.8=e^{\frac{\ln 1.8}{3.69}t}.$$We can take the natural logarithm of both sides to get $$\ln 1.8=\frac{\ln 1.8}{3.69}t.$$We can solve for $t$ to get $$t=3.69.$$', '["Separate the variables $P$ and $t$ and integrate both sides.", "Use the initial condition $P_0=100$ to find the value of $C$.", "Substitute $P=500$ and $K=1000$ into the equation and simplify.", "Take the natural logarithm of both sides and solve for $t$."]', '\frac{dP}{dt}=rP\left(1-\frac{P}{K}\right)', 'biology.ecosystem.population_growth_logistic_exponential_r_k_selection', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (NEET_EASY->NEET_MEDIUM) based on ELO score 1900 and target exam NEET', '2026-05-22T14:26:25.860Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca5ed15708631013d819e658ed85d08d', 'JEEMains', '11', 'Physics', 'phy_11_rot_rolling', 'Rotational Motion', 'Rolling without Slipping', '[]', '["rolling motion","linear acceleration","moment of inertia","solid cylinder"]', 0, 0, '[]', 'MCQ', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A solid cylinder of mass \(m\) and radius \(R\) rolls without slipping down an incline of angle \(\theta\). Which of the following expressions gives the linear acceleration \(a\) of its centre of mass?', '["\\(a = \\frac{g\\sin\\theta}{1+\\frac{1}{2}}\\)", "\\(a = \\frac{g\\sin\\theta}{1+\\frac{2}{3}}\\)", "\\(a = \\frac{g\\sin\\theta}{1+\\frac{1}{3}}\\)", "\\(a = g\\sin\\theta\\)"]', '\(a = \frac{g\sin\theta}{1+\frac{1}{2}}\)', 'For rolling without slipping, \(a = \frac{g\sin\theta}{1+\frac{I}{mR^2}}\). For a solid cylinder, \(I = \frac{1}{2}mR^2\). Substituting gives \(a = \frac{g\sin\theta}{1+\frac{1}{2}}\).', '["Step 1: Write the relation \\(a = \\frac{g\\sin\\theta}{1+\\frac{I}{mR^2}}\\).", "Step 2: Use the moment of inertia for a solid cylinder \\(I = \\frac{1}{2}mR^2\\).", "Step 3: Substitute \\(I\\) into the formula and simplify."]', 'a = \frac{g\sin\theta}{1+\frac{I}{mR^2}}', 'physics.rotational.rolling_acceleration', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:46:04.657Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca5efcc62f80186d76e8444ef5eef4ba', 'JEEMains', '12', 'Physics', 'phy_12_jm_current_electricity', 'Current Electricity', 'Current Electricity', '[]', '["Current Electricity"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 2, -1.0, '$V = IR$', '["$V = IR$", "$V = \frac{I}{R}$", "$V = I + R$", "$V = I - R$"]', '$V = IR$', 'Step 1: Recall Ohm''s law. Step 2: Use Ohm''s law to find the voltage across a resistor.', '["Step 1: Recall Ohm''s law.", "Step 2: Use Ohm''s law to find the voltage across a resistor."]', '$V = IR$', 'physics.emi.ohms_law', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:39:48.993Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca6076d19f6e51ff8a991ca94ba14a5b', 'NEET', '11', 'Biology', 'bio_11_neet_cellular_respiration', 'Cellular Respiration', 'ATP yield in aerobic vs anaerobic pathways', '[]', '["ATP synthesis","Aerobic respiration","Anaerobic fermentation","Glycolysis","Plant metabolism"]', 0, 0, '[]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 3, -1.0, 'During cellular respiration in plants, how many molecules of ATP are produced per molecule of glucose under (a) aerobic conditions and (b) anaerobic fermentation?', '["38 and 2", "36 and 2", "32 and 4", "30 and 0"]', '38 and 2', 'Aerobic respiration in plant cells yields about 38 ATP per glucose molecule (including substrate‑level phosphorylation and oxidative phosphorylation). Anaerobic fermentation (e.g., alcoholic fermentation) yields only the 2 ATP from glycolysis.', '["Step 1: Recall that complete oxidation of one glucose molecule in aerobic respiration gives ~38 ATP.", "Step 2: Recognize that anaerobic fermentation bypasses the electron transport chain, producing only the 2 ATP from glycolysis.", "Step 3: Match the numbers with the option list to select the correct answer."]', 'Aerobic: 38 ATP per glucose; Anaerobic: 2 ATP per glucose', 'biology.cellular_respiration.atp_yield', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:47:35.454Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca61dcec68d0fb2e9ccb6ecd0bedfe11', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_homologous_series', 'Basic Organic Chemistry', 'Homologous series functional groups', '[]', '["homologous series","functional group","alcohol","ether","aldehyde","ketone","carboxylic acid","general formula"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 4, -1.0, 'Which of the following sets of compounds belongs to the same homologous series?

A. $\mathrm{CH_3OH},\ \mathrm{C_2H_5OH},\ \mathrm{C_3H_7OH}$

B. $\mathrm{CH_3OCH_3},\ \mathrm{C_2H_5OC_2H_5},\ \mathrm{CH_3OC_2H_5}$

C. $\mathrm{CH_3CHO},\ \mathrm{CH_3COCH_3},\ \mathrm{C_2H_5CHO}$

D. $\mathrm{CH_3COOH},\ \mathrm{CH_3CH_2OH},\ \mathrm{CH_3COCH_3}$', '["$\\mathrm{CH_3OH},\\ \\mathrm{C_2H_5OH},\\ \\mathrm{C_3H_7OH}$", "$\\mathrm{CH_3OCH_3},\\ \\mathrm{C_2H_5OC_2H_5},\\ \\mathrm{CH_3OC_2H_5}$", "$\\mathrm{CH_3CHO},\\ \\mathrm{CH_3COCH_3},\\ \\mathrm{C_2H_5CHO}$", "$\\mathrm{CH_3COOH},\\ \\mathrm{CH_3CH_2OH},\\ \\mathrm{CH_3COCH_3}$"]', '$\mathrm{CH_3OH},\ \mathrm{C_2H_5OH},\ \mathrm{C_3H_7OH}$', 'Homologous series have the same functional group and general formula, differing by $\mathrm{CH_2}$ units. Option A contains alcohols ($\mathrm{C_nH_{2n+1}OH}$) with increasing carbon chain. Option B has ethers but $\mathrm{CH_3OC_2H_5}$ is unsymmetrical and not a higher homologue. Option C mixes aldehydes and ketones. Option D contains different functional groups: carboxylic acid, alcohol, ketone.', '["Step 1: Recall that a homologous series has same functional group and successive members differ by $\\mathrm{CH_2}$", "Step 2: Identify functional groups in each option", "Step 3: Check if all compounds in a set have same functional group and increasing carbon chain", "Step 4: Confirm that only Option A satisfies both conditions"]', '', 'chemistry.orgchem.homologous_series_functional_group_mismatch', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:00:35.521Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca659df002909d7d6f83a71d787377da', 'JEEMains', '12', 'Physics', 'phy_12_jm_current_electricity', 'Current Electricity', 'Kirchhoff''s laws KVL KCL', '[]', '["kirchhoff_voltage_law","kirchhoff_current_law","loop_analysis","circuit_analysis","ohms_law","series_resistors","parallel_resistors"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 6, -1.0, 'In the given circuit, the current through the 3 \Omega resistor is to be calculated using Kirchhoff''s laws. The circuit consists of two loops: Loop 1 has a 6 V battery and a 2 \Omega resistor; Loop 2 (sharing the 3 \Omega resistor with Loop 1) has a 9 V battery and a 4 \Omega resistor. What is the current through the 3 \Omega resistor?', '["1.0 A", "1.5 A", "2.0 A", "0.5 A"]', '1.5 A', 'Apply Kirchhoff''s Voltage Law (KVL) to both loops. Let $I_1$ be current in Loop 1 and $I_2$ in Loop 2. For Loop 1: $6 - 2I_1 - 3(I_1 - I_2) = 0$. For Loop 2: $9 - 4I_2 - 3(I_2 - I_1) = 0$. Solve the system: $5I_1 - 3I_2 = 6$, $3I_1 - 7I_2 = -9$. Solving gives $I_2 = 1.5\,\text{A}$, so current through 3 \Omega is $I_1 - I_2 = 1.5\,\text{A}$.', '["Step 1: Assign loop currents $I_1$ and $I_2$", "Step 2: Apply KVL to each loop", "Step 3: Form equations: $6 - 2I_1 - 3(I_1 - I_2) = 0$, $9 - 4I_2 - 3(I_2 - I_1) = 0$", "Step 4: Simplify to $5I_1 - 3I_2 = 6$, $3I_1 - 7I_2 = -9$", "Step 5: Solve system of equations", "Step 6: Find $I_2 = 1.5\\,\\text{A}$"]', '\sum V = 0 in closed loop', 'physics.circuits.kvl_sign_convention', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:55:02.809Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca68067b1b937ccefab3b6b7449e267f', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_thermodynamics', 'Thermodynamics', 'Kirchhoff''s Equation', '[]', '["ΔH temperature dependence","ΔCp","Kirchhoff equation","standard enthalpy","thermodynamic calculations"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'The standard enthalpy change $\Delta H^{\circ}$ for a reaction at 298 K is –100 kJ mol⁻¹. The heat‑capacity change $\Delta C_{p}$ for the reaction is constant at 20 J mol⁻¹ K⁻¹. Using Kirchhoff''s equation, what is $\Delta H^{\circ}$ at 350 K?', '["–98.96 kJ mol⁻¹", "–101.04 kJ mol⁻¹", "–100 kJ mol⁻¹", "–99 kJ mol⁻¹"]', '–98.96 kJ mol⁻¹', 'Kirchhoff''s equation gives $\Delta H_{T_2}=\Delta H_{T_1}+\int_{T_1}^{T_2}\Delta C_{p}\,dT$. With constant $\Delta C_{p}$, the integral becomes $\Delta C_{p}(T_2-T_1)$. Converting $\Delta C_{p}=20\,\text{J}=0.020\,\text{kJ}$, we have $\Delta H_{350}= -100\,\text{kJ}+0.020\,(350-298)= -100+1.04= -98.96\,\text{kJ}$.', '["Step 1: Write Kirchhoff''s equation $\\Delta H_{T_2}=\\Delta H_{T_1}+\\Delta C_{p}(T_2-T_1)$ for constant $\\Delta C_{p}$.", "Step 2: Convert $\\Delta C_{p}=20\\,\\text{J}=0.020\\,\\text{kJ\\,K}^{-1}$.", "Step 3: Substitute $T_1=298\\,\\text{K}$, $T_2=350\\,\\text{K}$ and compute $\\Delta H_{350}= -100+0.020\\times52$.", "Step 4: Obtain $\\Delta H_{350}= -98.96\\,\\text{kJ\\,mol}^{-1}$."]', 'ΔH_{T2}=ΔH_{T1}+∫_{T1}^{T2}ΔC_{p}dT', 'chem.thermo.kirchhoff_linear', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:32:09.399Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca6b1f1fa019bb0581561a967e42dfa1', 'JEEMains', '11', 'Physics', 'phy_11_jm_motion_in_a_straight_line', 'Motion in a Straight Line', 'Reaction time stopping distance', '[]', '["reaction time","stopping distance","initial velocity"]', 0, 0, '[]', 'Integer', NULL, 0, 1800, 'JEE_MAINS_EASY', 2, 0.0, '$\text{The reaction time is the time taken by a person to react to a stimulus and is given by the equation}$ $$\text{reaction time = stopping distance / initial velocity.}$', '[]', 'stopping distance / initial velocity', 'The reaction time is the time taken by a person to react to a stimulus and is given by the equation reaction time = stopping distance / initial velocity. This equation is derived from the definition of reaction time and the relationship between stopping distance and initial velocity.', '["Step 1: Recall the definition of reaction time", "Step 2: Derive the equation for reaction time"]', 'reaction time = stopping distance / initial velocity', 'general.exam_trap', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:21:20.879Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca6ef822d0dfb7f80ea9c9e6a7447ee4', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_inorganic_reactions', 'Inorganic Chemistry', 'Oxidation state in complex mixed‑valence', '["chem_12_ja_coordination_chemistry"]', '["mixed_valence","oxidation_state","intervalence_charge_transfer","coordination_complex","electron_distribution"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'Consider the mixed‑valence complex [Fe₂(SCN)₆]⁴⁻. Which of the following statements are true? (Select all that apply)', '["Both Fe atoms are in the +2 oxidation state.", "One Fe atom is +2 and the other is +3.", "The average oxidation state of Fe is +2.5.", "The complex exhibits intervalence charge transfer between Fe(II) and Fe(III)."]', '["ONE FE ATOM IS +2 AND THE OTHER IS +3.", "THE AVERAGE OXIDATION STATE OF FE IS +2.5.", "THE COMPLEX EXHIBITS INTERVALENCE CHARGE TRANSFER BETWEEN FE(II) AND FE(III)."]', 'In [Fe₂(SCN)₆]⁴⁻ the two iron centers are inequivalent: one is Fe(II) and the other Fe(III). Their sum gives +5, which together with six SCN⁻ (‑6) yields the overall charge of ‑4. Hence the average oxidation state is (+2 + +3)/2 = +2.5, and intervalence charge transfer is observed.', '["Step 1: Assign oxidation number – each SCN⁻ contributes –1 (total –6).", "Step 2: Let oxidation states be x and y; x + y – 6 = ‑4 ⇒ x + y = +2. Since the complex is known to be mixed‑valent, choose x = +2, y = +3.", "Step 3: Compute average oxidation state: (+2 + +3)/2 = +2.5.", "Step 4: Recognise that mixed‑valence complexes show intervalence charge transfer (IVCT) between Fe(II) and Fe(III)."]', 'Overall charge = Σ(oxidation numbers of metals) + Σ(charges of ligands)', 'chemistry.inorganic.mixed_valence_oxidation_state', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:05:20.648Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca7523268e59b7db0d0c2787fe5abeb2', 'NEET', '11', 'Biology', 'bio_11_neet_respiration', 'Respiration in Plants', 'Respiratory quotient RQ calculation', '[]', '["respiratory quotient","RQ","fat oxidation","substrate type"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 2, -1.0, 'If a substrate has RQ = 0.7, the respiratory substrate is likely:', '["Carbohydrate", "Fat", "Protein", "Organic acid"]', 'Fat', 'RQ = CO₂ released / O₂ consumed. Fat oxidation gives RQ ≈ 0.7 due to less CO₂ per O₂.', '["Step 1: Recall RQ formula", "Step 2: Match RQ = 0.7 to substrate", "Step 3: Fat has lowest RQ"]', 'RQ = \frac{CO_2}{O_2}', 'bio.respiration.rq_value_mismatch', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:06:33.741Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca81a6aa66b22e127f6a4ea661a8be83', 'JEEMains', '11', 'Mathematics', 'math_11_jm_binomial', 'Binomial Theorem', 'Middle term of expansion', '[]', '["binomial theorem","middle term","combinatorial coefficient","algebraic expansion"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Find the middle term in the expansion of \((x+2y)^{10}\).', '["252\\,x^{5}(2y)^{5}", "8064\\,x^{5}y^{5}", "1024\\,x^{5}y^{5}", "5040\\,x^{5}y^{5}"]', '8064\,x^{5}y^{5}', 'For \((a+b)^n\) the \((r+1)^{\text{th}}\) term is \(\binom{n}{r}a^{n-r}b^{r}\). With \(n=10\) the middle term is the 6th term (\(r=5\)). Substituting \(a=x\) and \(b=2y\) gives \(\binom{10}{5}x^{5}(2y)^{5}=252\times32\,x^{5}y^{5}=8064\,x^{5}y^{5}\).', '["Step 1: Identify the middle term index: for n=10, middle term is the 6th term (r=5).", "Step 2: Apply the binomial term formula \\(\\binom{10}{5}x^{5}(2y)^{5}\\).", "Step 3: Compute \\(\\binom{10}{5}=252\\) and \\((2y)^{5}=32y^{5}\\).", "Step 4: Multiply to obtain \\(252\\times32=8064\\) giving the term \\(8064x^{5}y^{5}\\)."]', 'T_{r+1}=\binom{n}{r}a^{n-r}b^{r}', 'mathematics.algebra.binomial_middle_term', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:15:44.958Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca8485c27e33e6f03e9d9a1e2f495e06', 'NEET', '11', 'Biology', 'bio_11_neet_photosynthesis', 'Photosynthesis', 'Light reactions – Z‑scheme', '[]', '["photophosphorylation","photosystem I","photosystem II","electron transport","ATP synthesis","NADPH"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 4, -1.0, 'In the Z‑scheme of photosynthetic electron transport, which of the following correctly describes the difference between cyclic and non‑cyclic photophosphorylation?', '["Cyclic photophosphorylation produces NADPH, whereas non‑cyclic does not.", "Cyclic photophosphorylation involves only Photosystem I, while non‑cyclic uses both Photosystem II and I.", "Cyclic photophosphorylation releases O₂, while non‑cyclic does not.", "Cyclic photophosphorylation occurs in the dark, whereas non‑cyclic occurs only in light."]', 'Cyclic photophosphorylation involves only Photosystem I, while non‑cyclic uses both Photosystem II and I.', 'In cyclic photophosphorylation electrons return to PSI after passing through the electron transport chain, generating ATP only. Non‑cyclic flow goes from PSII → PSI, producing both ATP and NADPH and evolving O₂.', '["Step 1: Identify the two types of photophosphorylation in the Z‑scheme.", "Step 2: Recall that cyclic involves only PSI and recycles electrons back to the reaction centre.", "Step 3: Remember that non‑cyclic uses both PSII and PSI, producing NADPH and O₂.", "Step 4: Match the description to the correct option."]', '', 'bio.photosynthesis.cyclic_vs_nonc', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:28:30.585Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca861512d827decc78b77c4b14e535dd', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_basic_organic', 'Basic Organic Chemistry', 'Electrophiles and nucleophiles types', '[]', '["nucleophile","electrophile","electron donor","charged species"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 2, -1.0, 'Which of the following is a nucleophile?', '["$\\mathrm{NO}_2^+$", "$\\mathrm{CH}_3^+$", "$\\mathrm{OH}^-$", "$\\mathrm{AlCl}_3$"]', '$\mathrm{OH}^-$', 'Nucleophiles donate electron pairs; $\mathrm{OH}^-$ has lone pair and negative charge.', '["Step 1: Identify species with lone pairs/charge", "Step 2: $\\mathrm{OH}^-$ donates electrons to electrophiles"]', '', 'chemistry.organic.species_misidentification', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:12:01.434Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca88849ed516ff51f99222a86287731f', 'JEEMains', '11', 'Mathematics', 'mat_11_jm_binomial', 'Binomial Theorem', 'Approximation using binomial', '[]', '["binomial approximation","small x expansion","linear approximation","numerical estimation"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, 0.0, 'Using binomial approximation, what is $(1 + 0.01)^5$ approximately?', '[]', '1.05', '$(1+x)^n \approx 1 + nx$ for small $x$. Here $x=0.01$, $n=5$.', '["Apply $ (1+x)^n \\approx 1 + nx $", "Substitute $x=0.01$, $n=5$", "Compute $1 + 5\\times0.01 = 1.05$"]', '(1+x)^n \approx 1 + nx', 'math.binomial.higher_order_missed', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:50:46.516Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca92c4825fefe65cb3b65d39f495fd1b', 'JEEMains', '11', 'Physics', 'phy_11_jm_waves', 'Waves', 'Transverse and longitudinal wave properties', '["phy_11_jm_wave_motion"]', '["transverse wave","longitudinal wave","particle displacement","wave propagation direction","wavelength","wave speed"]', 1, 0, '["NEET"]', 'Multi-correct', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, -1.0, 'A transverse wave and a longitudinal wave travel through the same medium with the same frequency. Which of the following properties differ between the two waves?

I. Direction of particle oscillation relative to wave propagation

II. Wavelength

III. Speed

IV. Amplitude', '["I only", "I and II only", "I, II, and III", "I, II, III, and IV"]', '["I ONLY"]', 'Only statement I is always true: transverse waves have perpendicular oscillations, longitudinal have parallel. Wavelength, speed, and amplitude depend on medium and source, not wave type. For same frequency and medium, speed is same, so wavelength $\lambda = v/f$ is also same. Amplitude is independent. Thus only I differs fundamentally.', '["Step 1: Recall transverse: particles oscillate perpendicular to propagation", "Step 2: Longitudinal: particles oscillate parallel to propagation → I is correct", "Step 3: Speed depends on medium, same for both → III same", "Step 4: Frequency same, speed same → wavelength $\\lambda = v/f$ same → II same", "Step 5: Amplitude is independent of wave type → IV same"]', '', 'physics.waves.wavelength_dependence_on_type', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:17:17.307Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca9c7cbc8224e656f58224c3a17ccbc2', 'NEET', '11', 'Biology', 'bio_11_neet_plant_physiology', 'Plant Physiology Advanced', 'Ascent of sap — cohesion-tension transpiration pull theory', '[]', '["transpiration pull","cohesion-tension theory","xylem transport","ascent of sap"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1720, 'NEET_EASY', 2, -1.0, 'According to the cohesion-tension theory, the ascent of sap in plants mainly depends on:', '["Root pressure", "Guttation", "Transpiration pull", "Capillary action"]', 'Transpiration pull', '[Duplicate Quarantined] Transpiration creates tension, pulling water up via cohesive forces.', '["Step 1: Transpiration generates negative pressure", "Step 2: Cohesion maintains continuous water column"]', '', 'biology.plant_physiology.transpiration_misconception', 'NEET Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:22:46.196Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ca9cb9444d31e4550dbf588ff3f0b104', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_d_and_f_block', 'd and f Block Elements', 'Variable oxidation states magnetic properties colour', '[]', '["oxidation states","d-block","manganese","electron configuration"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'Which d-block element shows maximum number of oxidation states in its compounds?', '["Sc", "Mn", "Zn", "Cu"]', 'Mn', 'Mn (Z=25) has electronic configuration [Ar] 3d⁵4s², allowing +2 to +7 oxidation states.', '["Step 1: Check d-electron count", "Step 2: Mn has half-filled stability", "Step 3: Exhibits +2 to +7 states"]', '', 'chem.dblock.oxidation_state_memory', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:33:36.754Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('caa018de84d22948e36d279d63d45591', 'JEEMains', '12', 'Physics', 'phy_12_jm_semiconductor_electronics', 'Semiconductor Electronics', 'Semiconductors and Devices', '[]', '["Intrinsic semiconductors","Impurities","Semiconductor properties"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 2, -1.0, 'Intrinsic semiconductors are those in which', '["The conduction band is completely empty", "The valence band is completely full", "There are no impurities present", "The Fermi level is at the center of the forbidden gap"]', 'There are no impurities present', 'Intrinsic semiconductors are those in which there are no impurities present. This means that the semiconductor is made up of only one type of material, and there are no foreign atoms or molecules present that can affect its electrical properties. Intrinsic semiconductors have a high resistivity and are not very useful for electronic applications.', '["Step 1: Recall the definition of intrinsic semiconductors", "Step 2: Identify the correct option"]', '', 'physics.semiconductors.intrinsic', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:21:00.400Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('caa1baa016163ccf47e22179a2905c3d', 'Board', '8', 'Science', 'sci_8_board_light', 'Light', 'Dispersion of light rainbow colours', '[]', '["dispersion","rainbow","spectrum","wavelength"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 850, 'CLASS_8_RECALL', 2, 0.0, 'Which colour appears at the top of a primary rainbow?', '["Red", "Violet", "Blue", "Green"]', 'Red', 'In a rainbow, red bends least and appears on the outer edge (top).', '["Dispersion order: red to violet", "Red has largest wavelength, least deviation"]', '', 'physics.light.rainbow_order', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:05:15.056Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('caa1de454b8b346161f6c21e82ef040c', 'Board', '10', 'Science', 'phy_10_board_lens', 'Optics', 'Lens formula and magnification', '[]', '["lens formula","sign convention","real image","magnification","converging lens"]', 0, 0, '[]', 'MCQ', NULL, 0, 1280, 'BOARD_EASY', 4, 0.0, 'A converging lens has a focal length of 15 cm. An object is placed 30 cm in front of the lens. Using the lens formula, determine the nature of the image and its magnification. Choose the correct statement.', '["Real, inverted image; magnification = -1", "Real, inverted image; magnification = -2", "Virtual, upright image; magnification = +2", "Virtual, upright image; magnification = +0.5"]', 'Real, inverted image; magnification = -2', 'Using 1/f = 1/v + 1/u, we get 1/15 = 1/v + 1/(-30) ⇒ 1/v = 1/15 + 1/30 = 2/30 + 1/30 = 3/30 ⇒ v = 10 cm (real, on the opposite side). Magnification m = v/u = 10/(-30) = -1/3 ≈ -0.33. Wait, this does not match any option. Re‑checking: u = -30 cm, f = +15 cm, so 1/v = 1/15 - 1/30 = (2-1)/30 = 1/30 ⇒ v = 30 cm, m = 30/(-30) = -1. Hence the correct answer is "Real, inverted image; magnification = -1". (Option A).', '["Step 1: Write the lens formula 1/f = 1/v + 1/u with sign conventions (f > 0 for converging, u negative).", "Step 2: Substitute f = +15 cm and u = -30 cm and solve for image distance v.", "Step 3: Compute magnification m = v/u.", "Step 4: Determine the nature of the image from the sign of v (positive ⇒ real) and sign of m (negative ⇒ inverted)."]', '1/f = 1/v + 1/u, m = v/u', 'physics.optics.lens_formula_sign', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:53:41.782Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('caa2e93cbd239f2c0479f438301e572f', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_chemical_bonding', 'Chemical Bonding', 'Dipole moment - polar covalent bonds', '[]', '["dipole moment","molecular polarity","VSEPR theory","polar bonds","symmetry"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 2, -1.0, 'Which molecule has a net dipole moment?', '["$\\text{CO}_2$", "$\\text{BF}_3$", "$\\text{CHCl}_3$", "$\\text{CCl}_4$"]', '$\text{CHCl}_3$', '$\text{CHCl}_3$ is polar due to asymmetric tetrahedral geometry; others are symmetric and nonpolar.', '["Step 1: Check molecular symmetry", "Step 2: $\\text{CHCl}_3$ has unequal dipole cancellation", "Step 3: Others have symmetric dipole cancellation"]', '', 'chemistry.bonding.dipole_symmetry_misconception', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:13:50.206Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('caa327748d5b08188e25ff465bfdcb50', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jee_combinatorics', 'Advanced Combinatorics', 'Integer partition into distinct/equal parts', '[]', '["integer partition","distinct parts","combinations"]', 0, 0, '[]', 'MCQ', NULL, 0, 2500, 'JEE_ADV_EASY', 1, -2.0, 'The number of ways to partition $n$ identical items into $r$ distinct parts is given by the formula $\boxed{\binom{n+r-1}{r-1}}$.', '["$\\binom{n+r-1}{r-1}$", "$\\binom{n+r-1}{n}$", "$\\binom{n+r-1}{r}$", "$\\binom{n+r-1}{n+r}$"]', '$\binom{n+r-1}{r-1}$', 'Step 1: The number of ways to partition $n$ identical items into $r$ distinct parts is given by the formula $\binom{n+r-1}{r-1}$.', '["Step 1: Use the formula for combinations to find the number of ways to partition $n$ identical items into $r$ distinct parts."]', 'Integer partition formula', 'math.comb.combinatorics', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:07:04.017Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('caa49fb0e7e27b84ec57a32d6bd42427', 'JEEMains', '12', 'Physics', 'phy_12_jm_gauss', 'Electrostatics', 'Gauss''s Law – Symmetry Applications', '["phy_12_jm_electric_fields"]', '["Gauss law","electric field","infinite plane","surface charge density","symmetry"]', 1, 0, '["JEEAdvanced"]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'A large, uniformly charged infinite plane carries a surface charge density $\sigma$. What is the magnitude of the electric field just outside the plane (in vacuum)?', '["$E = \\dfrac{\\sigma}{2\\varepsilon_0}$ directed outward on both sides of the plane.", "$E = \\dfrac{\\sigma}{\\varepsilon_0}$ directed outward on both sides of the plane.", "$E = \\dfrac{\\sigma}{2\\varepsilon_0}$ directed outward on one side only.", "$E = 0$ inside the plane."]', '$E = \dfrac{\sigma}{2\varepsilon_0}$ directed outward on both sides of the plane.', 'Applying Gauss''s law to a pill‑box Gaussian surface that straddles the plane gives $\oint \mathbf{E}\cdot d\mathbf{A}=\sigma A/\varepsilon_0$. The field is the same on both faces, yielding $E=\sigma/(2\varepsilon_0)$ outward on each side.', '["Step 1: Choose a cylindrical (pill‑box) Gaussian surface of area $A$ intersecting the plane.", "Step 2: Write Gauss''s law: $\\oint \\mathbf{E}\\cdot d\\mathbf{A}=\\dfrac{Q_{enc}}{\\varepsilon_0}=\\dfrac{\\sigma A}{\\varepsilon_0}$.", "Step 3: Recognize that the flux through the curved side is zero; only the two flat faces contribute $E A$ each.", "Step 4: Solve $2EA = \\sigma A/\\varepsilon_0$ to obtain $E = \\sigma/(2\\varepsilon_0)$."]', '$\oint \mathbf{E}\cdot d\mathbf{A}=\dfrac{Q_{enc}}{\varepsilon_0}$', 'physics.electricity.gausslaw.field_direction', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:35:12.346Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('caa73d50a01c41a10476f2dcf1499acc', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_magnetism', 'Magnetic Force Advanced', 'Induced emf', '[]', '["magnetic force","induced emf"]', 0, 0, '[]', 'Integer', NULL, 0, 2450, 'JEE_ADV_EASY', 3, -1.0, 'A coil of $10$ turns is placed in a magnetic field of $0.1$ T. If the coil is rotated by $90^\circ$ in $0.1$ s, find the induced emf.', '[]', '0.628', 'The induced emf can be found using the formula $\epsilon = -N\frac{d\phi}{dt}$.', '["Step 1: Calculate the initial flux", "Step 2: Calculate the final flux", "Step 3: Find the change in flux"]', '', 'phy.magnetism.induced_emf', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:08:20.375Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('caadd4a7cf30ec11db3ac71d7be981ca', 'JEEMains', '11', 'Physics', 'phy_11_jm_gravitation', 'Gravitation', 'Gravitational potential energy', '[]', '["gravitational field","potential energy","inverse square law","mass interaction","energy sign convention"]', 0, 0, '[]', 'MCQ', NULL, 0, 1885, 'JEE_MAINS_EASY', 3, -1.0, 'The gravitational field intensity at a distance $r$ from a point mass $M$ is given by $g = -\frac{GM}{r^{2}}$. Which of the following statements is correct about the gravitational potential energy $U$ of a test mass $m$ placed at that point?', '["$U = -\\frac{GMm}{r}$", "$U = \\frac{GMm}{r}$", "$U = -\\frac{GMm}{r^{2}}$", "$U = \\frac{GMm}{r^{2}}$"]', '$U = -\frac{GMm}{r}$', 'Gravitational potential energy is defined as $U = -\int g\,dm = -\frac{GMm}{r}$, with the negative sign indicating a bound system.', '["Step 1: Recall the relation between field intensity and potential: $g = -\\frac{dU}{dr}$.", "Step 2: Integrate $g$ with respect to $r$ to obtain $U = -\\frac{GMm}{r} + C$ (constant taken as zero at infinity).", "Step 3: Choose the option that matches the derived expression."]', '$U = -\frac{GMm}{r}$', 'physics.gravitation.potential_energy_sign', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:43:29.137Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cab0b268c9af29a083dc874fec655098', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_biomolecules', 'Chemistry', 'Biomolecules', '[]', '["enzyme specificity","induced fit","competitive inhibition","cofactor requirement"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'Which of the following statements is NOT true about enzyme‑substrate specificity?', '["The induced‑fit model explains conformational change of the active site.", "The enzyme active site is rigid.", "Competitive inhibitors resemble the substrate.", "Cofactors may be required for activity."]', 'The enzyme active site is rigid.', 'Enzyme active sites are flexible; they adapt to the substrate (induced‑fit). Hence the statement that the active site is rigid is false, while the other three statements are true.', '["Step 1: Recall that enzyme specificity is explained by the induced‑fit model.", "Step 2: Identify which option contradicts this model.", "Step 3: Recognize that a rigid active site opposes the induced‑fit concept.", "Step 4: Choose the option stating the active site is rigid."]', '', 'chem.bioenzyme.specificity', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:37:33.951Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cab27ac5519776728f5f92d036281b5a', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_molecular_orbital', 'Molecular Orbital Theory', 'Bonding and antibonding in diatomic molecules', '["chem_11_jm_diatomic_mo"]', '["bond order","molecular orbitals","O2","antibonding","electron configuration"]', 1, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'According to Molecular Orbital theory, what is the bond order of the O$_2$ molecule?', '["2", "1", "0", "3"]', '2', 'In O$_2$, the configuration up to $\pi_{2p}$ gives 2 electrons in bonding and 2 in antibonding $\pi^*$ orbitals, giving bond order $=\frac{(8-4)}{2}=2$.', '["Step 1: Fill molecular orbitals for O$_2$ up to $\\pi_{2p}$.", "Step 2: Count electrons in bonding (8) and antibonding (4) orbitals.", "Step 3: Apply bond order formula $\\frac{N_b-N_a}{2}$."]', 'Bond order = \frac{N_{bonding}-N_{antibonding}}{2}', 'chemistry.mo.bond_order_miscount', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:39:01.667Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cab38e4ee2e2a43ddae11cab4b1815d8', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_number_theory', 'Number Theory', 'Euclid''s GCD algorithm', '[]', '["gcd","euclidean algorithm","modular arithmetic","divisibility"]', 0, 0, '[]', 'Integer', NULL, 0, 2430, 'JEE_ADV_EASY', 3, -1.0, 'What is the greatest common divisor (GCD) of 84 and 119 using the Euclidean algorithm?', '[]', '7', 'Apply Euclidean algorithm: 119 mod 84 = 35, 84 mod 35 = 14, 35 mod 14 = 7, 14 mod 7 = 0 → GCD = 7.', '["Step 1: 119 % 84 = 35", "Step 2: 84 % 35 = 14 → 35 % 14 = 7", "Step 3: 14 % 7 = 0 → GCD = 7"]', '\gcd(a,b) = \gcd(b, a \mod b)', 'math.number_theory.gcd.modulo_order', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:50:42.355Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cab42b7e9aee41918b0f803a65ff0946', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_thermodynamics', 'Thermodynamics', 'Gibbs free energy standard conditions', '[]', '["Gibbs free energy","equilibrium constant","standard conditions"]', 0, 0, '[]', 'Integer', NULL, 0, 1800, 'JEE_MAINS_EASY', 2, 0.0, '$\text{The standard Gibbs free energy change for the reaction}$ $$\text{C(s) + O}_2(g) \to \text{CO}_2(g)$ is given by the equation}$ $$\Delta G^\circ = -RT \ln K$$', '[]', '-RT \ln K', 'The standard Gibbs free energy change for the reaction is given by the equation \Delta G^\circ = -RT \ln K. This equation is derived from the definition of Gibbs free energy and the equilibrium constant K.', '["Step 1: Recall the definition of Gibbs free energy", "Step 2: Derive the equation for standard Gibbs free energy change"]', '\Delta G^\circ = -RT \ln K', 'general.exam_trap', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:21:20.852Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cab6725d286a119fdd9f922f5b8c2d3d', 'NEET', '11', 'Biology', 'bio_11_neet_plant_physiology', 'Plant Physiology Advanced', 'Mineral deficiency symptoms — specific element identification', '[]', '["mineral deficiency","nitrogen","chlorosis","mobile nutrients"]', 1, 0, '["Board"]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 2, -1.0, 'Yellowing of leaves starting from older ones suggests deficiency of which element?', '["Nitrogen", "Iron", "Magnesium", "Calcium"]', 'Nitrogen', 'Nitrogen deficiency causes chlorosis in older leaves first due to its mobility in plants.', '["Step 1: Recall mobile vs immobile nutrients", "Step 2: Nitrogen is mobile, affects older leaves"]', '', 'biology.plant.deficiency_symptom_misidentification', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:17:12.843Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cabe0fa4e7bc856d4aebe2ddfc0ceed6', 'JEEMains', '12', 'Physics', 'phy_12_jm_electrostatics', 'Electric Charges and Fields', 'Coulomb''s law and superposition', '[]', '["Coulomb''s law","electrostatic force","superposition","point charge"]', 0, 0, '[]', 'Integer', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, 0.0, 'Two point charges, \(q_{1}=+3\,\mu\text{C}\) and \(q_{2}=-4\,\mu\text{C}\), are placed \(0.05\,\text{m}\) apart in vacuum. Find the magnitude of the net electrostatic force on \(q_{1}\) due to \(q_{2}\). Use \(k=9\times10^{9}\,\text{N·m}^{2}\!\!/\text{C}^{2}\). Give your answer in newtons (N) rounded to two decimal places.', '[]', '43.2', 'Coulomb''s law: \(F = k\frac{|q_{1}q_{2}|}{r^{2}}\). Substituting the values gives \(F = 9\times10^{9}\times\frac{(3\times10^{-6})(4\times10^{-6})}{(0.05)^{2}} = 43.20\,\text{N}\).', '["Step 1: Compute the product of the charges: \\(|q_{1}q_{2}| = 3\\times10^{-6}\\times4\\times10^{-6}=1.2\\times10^{-11}\\).", "Step 2: Square the separation distance: \\(r^{2} = (0.05)^{2}=2.5\\times10^{-3}\\).", "Step 3: Apply Coulomb''s law: \\(F = 9\\times10^{9}\\times\\frac{1.2\\times10^{-11}}{2.5\\times10^{-3}} = 43.20\\,\\text{N}\\)."]', 'F = k \frac{|q_{1}q_{2}|}{r^{2}}', 'physics.electrostatics.coulomb_sign_misinterpretation', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:33:42.220Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cac199eea8d480b543e1ca4e5f002672', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_electrochemistry', 'Electrochemistry', 'Cell notation and EMF calculation', '[]', '["standard EMF","galvanic cell","reduction potential","cell notation","Nernst equation"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, 0.0, 'Consider the galvanic cell: Cu(s) | Cu²⁺ (0.10 M) || Fe²⁺ (0.10 M) | Fe(s). The standard reduction potentials are E°(Cu²⁺/Cu) = +0.34 V and E°(Fe²⁺/Fe) = –0.44 V. What is the standard electromotive force (EMF) of the cell at 25 °C?', '[]', '0.78', 'The cathode is the Cu²⁺/Cu couple (+0.34 V) and the anode is the Fe²⁺/Fe couple (–0.44 V). EMF = E°cathode – E°anode = 0.34 – (‑0.44) = 0.78 V.', '["Step 1: Identify the half‑reaction with the higher reduction potential as the cathode (Cu²⁺/Cu).", "Step 2: Write the anode half‑reaction (Fe²⁺/Fe) with its potential.", "Step 3: Apply E_cell = E°cathode – E°anode to obtain 0.78 V."]', 'E_cell = E°cathode – E°anode', 'chemistry.electrochemistry.emf_cell_notation', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:56:45.904Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cac4ff2864a84a6fbe7142a12b17477d', 'JEEMains', '11', 'Physics', 'phy_11_jm_thermodynamics', 'Thermodynamics', 'Second law entropy statements', '[]', '["entropy","second law of thermodynamics","cyclic process","universe entropy"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, -1.0, 'The second law of thermodynamics implies that in any cyclic process, the total entropy change of the universe is:', '["Zero", "Negative", "Positive", "Greater than or equal to zero"]', 'Greater than or equal to zero', 'Entropy of the universe increases or remains constant; never decreases in any real process.', '["Step 1: Second law → $\\Delta S_{\\text{univ}} \\geq 0$", "Step 2: Equality for reversible, >0 for irreversible"]', '$\Delta S_{\text{univ}} \geq 0$', 'physics.thermo.entropy_sign_error', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:18:55.444Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cac87d577b1d15feb17aa663ac532a9e', 'JEEMains', '12', 'Chemistry', 'che_12_jm_surface_coagulation', 'Surface Chemistry', 'Coagulation and peptization', '[]', '["critical coagulation concentration","Schulze‑Hardy rule","valence effect","colloids","ionic strength"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'According to the Schulze‑Hardy rule, the critical coagulation concentration (CCC) of a colloidal sol is highest for which type of ion?

A. Divalent cation
B. Monovalent anion
C. Trivalent cation
D. Monovalent cation', '["Divalent cation", "Monovalent anion", "Trivalent cation", "Monovalent cation"]', 'Monovalent cation', 'The Schulze‑Hardy rule states that the coagulating power of ions increases with their valence. Hence, the CCC is lowest for highly charged ions and highest for ions of low charge. Among the choices, a monovalent cation has the smallest valence, giving the highest CCC.', '["Step 1: Recall the Schulze‑Hardy rule (CCC ∝ 1/|z|^6).", "Step 2: Identify the ion with the smallest absolute charge.", "Step 3: Choose the option that corresponds to a monovalent ion."]', 'CCC \propto \frac{1}{|z|^{6}}', 'chemistry.surface.coagulation_valence', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:10:17.247Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cacd12a4b61fcb44b076a964fcbc6ebb', 'NEET', '12', 'Biology', 'bio_12_neet_gene_mapping', 'Genetics', 'Gene mapping and recombination', '[]', '["recombination frequency","map units","centiMorgan","gene order","linkage","Morgan''s mapping function"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 4, -1.0, 'Three genes A, B, and C are located on the same chromosome. The recombination frequencies obtained from test crosses are: \(RF(A,B) = 10\%\), \(RF(B,C) = 12\%\), and \(RF(A,C) = 22\%\). Assuming no interference, determine the most likely order of the genes on the chromosome and the map distances (in centiMorgans) between adjacent genes.', '["A – B – C; AB = 10 cM, BC = 12 cM", "C – B – A; AB = 10 cM, BC = 12 cM", "A – B – C; AB = 10 cM, BC = 12 cM, AC = 22 cM", "C – A – B; AB = 10 cM, BC = 12 cM, AC = 22 cM"]', 'A – B – C; AB = 10 cM, BC = 12 cM, AC = 22 cM', 'The sum of the two smaller recombination frequencies (10% + 12% = 22%) equals the largest frequency (22%). This indicates that B lies between A and C. Hence the order is A‑B‑C with distances AB = 10 cM and BC = 12 cM, giving AC = 22 cM.', '["Step 1: List the three given recombination frequencies.", "Step 2: Check if the sum of any two smaller values equals the largest value (10% + 12% = 22%).", "Step 3: Conclude that the gene corresponding to the middle value (B) lies between the other two genes.", "Step 4: Assign the order A‑B‑C and record the map distances AB = 10 cM, BC = 12 cM, AC = 22 cM."]', 'Distance (cM) = recombination frequency (%)', 'biology.genetics.recombination_frequency', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:14:14.521Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cacd848efa0cc13a3e5af79098f927dd', 'NEET', '12', 'Biology', 'bio_12_neet_ecosystem', 'Ecosystem', 'Energy flow', '[]', '["GPP","NPP","energy flow","ecosystem productivity"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 4, -1.0, 'In an ecosystem, if the gross primary productivity (GPP) is 12,000 kcal/m/yr and the respiration loss by producers is 7,000 kcal/m/yr, what is the net primary productivity (NPP)?

(A) 5,000 kcal/m/yr

(B) 7,000 kcal/m/yr

(C) 12,000 kcal/m/yr

(D) 19,000 kcal/m/yr', '["5,000 kcal/m/yr", "7,000 kcal/m/yr", "12,000 kcal/m/yr", "19,000 kcal/m/yr"]', '5,000 kcal/m/yr', 'Net Primary Productivity (NPP) is calculated as GPP minus respiratory losses (R): $ NPP = GPP - R $. Substituting values: $ NPP = 12,000 - 7,000 = 5,000 $ kcal/m/yr. This represents energy available to consumers.', '["Step 1: Recall the formula: NPP = GPP - R", "Step 2: Identify given values: GPP = 12,000, R = 7,000", "Step 3: Subtract: 12,000 - 7,000 = 5,000", "Step 4: Assign correct unit: kcal/m/yr"]', 'NPP = GPP - R', 'biology.ecosystem.npp_formula_confusion', 'NEET', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:20:32.929Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cad6ab45a7a64a30bc0a822b385fc2c9', 'JEEMains', '12', 'Chemistry', 'chem_12_jadv_physical_chemistry', 'Advanced Physical Chemistry', 'Colligative properties – freezing point depression', '["chem_12_jadv_activity_coefficients"]', '["colligative property","freezing point depression","cryoscopic constant","molality","non‑ideal solution"]', 1, 0, '[]', 'Integer', NULL, 0, 2700, 'JEE_MAINS_HARD', 3, -1.0, 'For a binary solution of a non‑volatile solute in water at 298 K, the measured freezing point depression is $-1.5\,\text{°C}$. Assuming the cryoscopic constant of water is $K_f = 1.86\,\text{°C·kg·mol}^{-1}$, calculate the apparent molality $m_{\text{app}}$ of the solute (in mol·kg⁻¹). Give your answer to two decimal places.', '[]', '0.81', 'Freezing point depression follows $\Delta T_f = K_f \times m_{\text{app}}$. Hence $m_{\text{app}} = \frac{1.5}{1.86} \approx 0.8065$, which rounds to $0.81\,\text{mol·kg}^{-1}$.', '["Step 1: Write the freezing point depression formula $\\Delta T_f = K_f m$.", "Step 2: Substitute $\\Delta T_f = 1.5\\,\\text{°C}$ and $K_f = 1.86\\,\\text{°C·kg·mol}^{-1}$.", "Step 3: Solve for $m$ and round to two decimal places."]', '$\Delta T_f = K_f \times m$', 'chem.physical.freezing_point_depression', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (JEE_ADV_MEDIUM->JEE_MAINS_HARD) based on ELO score 2700 and target exam JEEMains', '2026-05-22T14:18:18.204Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cad7930c137146031366e2609bbfdfca', 'JEEMains', '12', 'Mathematics', 'math_12_jm_probability', 'Probability', 'Multiplication theorem (dependent events)', '[]', '["dependent events","conditional probability","fraction reduction","sampling without replacement"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, 0.0, 'A box contains 3 red, 4 green, and 5 blue balls. Two balls are drawn successively without replacement. What is the probability that the first ball is red and the second ball is green? Express your answer as a fraction in lowest terms and then give the denominator.', '[]', '11', 'First draw: $P(R)=3/12=1/4$. After removing a red ball, $11$ balls remain with $4$ green, so $P(G|R)=4/11$. The combined probability is $(1/4)(4/11)=1/11$, whose denominator in lowest terms is $11$.', '["Step 1: Compute $P(\\text{first red}) = 3/12$.", "Step 2: Compute $P(\\text{second green}\\,|\\,\\text{first red}) = 4/11$.", "Step 3: Multiply the two probabilities using the multiplication theorem.", "Step 4: Reduce the resulting fraction to lowest terms and read the denominator."]', '$P(A\cap B)=P(A)\,P(B|A)$', 'math.probability.dependent_events', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:14:37.378Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cad9abd39ea86e679ec2a3f2ee10eb24', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_biomolecules', 'Biomolecules', 'Amino acids essential non-essential', '[]', '["essential amino acids","lysine","non-essential amino acids","human nutrition","protein synthesis"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1750, 'JEE_MAINS_EASY', 2, -1.0, 'Which of the following amino acids is classified as essential in humans?', '["Alanine", "Glutamine", "Lysine", "Serine"]', 'Lysine', 'Essential amino acids cannot be synthesized; lysine must be obtained from diet.', '["Step 1: Recall essential amino acids list", "Step 2: Lysine is essential; others are non-essential"]', '', 'chemistry.biomolecules.amino_acid_classification', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (NEET_EASY->JEE_MAINS_EASY) based on ELO score 1750 and target exam JEEMains', '2026-05-22T15:37:57.666Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cadc7a046381b24f007f037e41651df7', 'JEEMains', '11', 'Physics', 'phy_11_jm_work_energy_power', 'Work Energy and Power', 'Work-energy theorem kinetic energy', '[]', '["kinetic energy","vector magnitude","work-energy theorem","scalar product"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, 0.0, 'A 2 kg block moves with velocity $v = 3\hat{i} + 4\hat{j}$ m/s. What is its kinetic energy?', '[]', '25', 'Speed squared is $v^2 = 3^2 + 4^2 = 25$, so $KE = \frac{1}{2}mv^2 = 25$ J.', '["Step 1: Compute $v^2 = 9 + 16 = 25$", "Step 2: $KE = 0.5 \\times 2 \\times 25 = 25$ J"]', '$KE = \frac{1}{2}mv^2$', 'physics.work_energy.power_vector_split', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:51:22.736Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('caeb1d51709fc22aed8b9b8d859c1e9a', 'Board', '10', 'Science', 'phy_10_board_joule', 'Electricity', 'Joule''s heating effect', '[]', '["Joule''s law","heat energy","power","resistance","current"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 3, 0.0, 'A current of \(3\ \text{A}\) passes through a resistor of \(5\ \Omega\) for \(2\) minutes. What amount of heat energy is produced in the resistor?', '["5400 J", "1800 J", "900 J", "2700 J"]', '5400 J', 'Using Joule''s law \(Q = I^{2} R t\): \(I = 3\ \text{A}, R = 5\ \Omega, t = 2\text{ min}=120\text{ s}\). Hence \(Q = 3^{2} \times 5 \times 120 = 5400\ \text{J}\).', '["Step 1: Convert the time to seconds (2 min = 120 s).", "Step 2: Apply Joule''s law \\(Q = I^{2} R t\\).", "Step 3: Substitute the values and compute the product."]', 'Q = I^{2} R t', 'physics.electricity.joule_law_energy', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:19:17', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Physics->Science) to match canonical taxonomy item sci_10_board_electricity', '2026-05-20T12:30:36.426Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('caec0b38a782332757d5308a188d6aaa', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_atomic_structure', 'Structure of Atom', 'Heisenberg uncertainty principle', '[]', '["heisenberg uncertainty","momentum uncertainty","position uncertainty","electron dynamics"]', 0, 0, '[]', 'Integer', NULL, 0, 1950, 'JEE_MAINS_EASY', 3, 0.0, 'If the uncertainty in position of an electron is $1.5\times10^{-10}\,\text{m}$, what is the minimum uncertainty in its speed? (Use $h = 6.6\times10^{-34}$, $m_e = 9.1\times10^{-31}$)', '[]', '3.86', 'Apply $\Delta x \cdot \Delta p \geq \frac{h}{4\pi}$, then $\Delta v = \frac{h}{4\pi m \Delta x}$.', '["Step 1: $\\Delta p \\geq \\frac{6.6\\times10^{-34}}{4\\pi \\times 1.5\\times10^{-10}}$", "Step 2: $\\Delta v \\geq \\frac{\\Delta p}{m} = \\frac{h}{4\\pi m \\Delta x}$", "Step 3: $\\Delta v \\approx 3.86\\times10^5\\,\\text{m/s} \\Rightarrow 3.86$ (in $10^5$ unit)"]', '\Delta x \cdot \Delta p \geq \frac{h}{4\pi}', 'chemistry.atomic_structure.uncertainty_unit_error', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:50:30.510Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('caf49ba2b3f8faadacb04d0615d160a1', 'JEEMains', '12', 'Physics', 'phy_12_jm_magnetism', 'Moving Charges and Magnetism', 'Cyclotron motion radius period', '[]', '["cyclotron","radius","magnetic field","charged particle motion","circular path"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, 0.0, 'A proton moves in a circular path in a cyclotron under a magnetic field of 0.5 T. If its speed is $3 \times 10^6$ m/s, what is the radius of its path?

$$
r = \frac{mv}{qB},\quad m_p = 1.67 \times 10^{-27}\,\text{kg}
$$', '[]', '0.06', 'Using $r = mv/(qB)$, radius calculates to 0.06 m.', '["r = (1.67e-27 × 3e6)/(1.6e-19 × 0.5)", "r = 0.06 m"]', 'r = mv/(qB)', 'physics.magnetism.radius_formula_confusion', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:19:14.407Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('caf4ca94d3c0b01c6c522c86ad397656', 'NEET', '12', 'Biology', 'bio_12_neet_biotechnology', 'Biotechnology', 'PCR steps Taq polymerase applications', '[]', '["PCR","Taq polymerase","DNA replication","thermostable enzyme","extension step","molecular biology","biotechnology"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1720, 'NEET_EASY', 1, -1.0, 'In PCR, what is the function of Taq polymerase?', '["Unwind DNA helix", "Add nucleotides to growing strand", "Cut DNA at specific sites", "Maintain pH stability"]', 'Add nucleotides to growing strand', 'Taq polymerase synthesizes new DNA strand by adding dNTPs during extension step at high temperature.', '["Taq polymerase is a DNA polymerase.", "It adds nucleotides in 5''→3'' direction at ~72°C."]', '', 'bio.biotech.pcr_enzyme_function_misattribution', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:09:29.414Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cafd8d0792551822d6d9e4c06fa12c7b', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_inorganic_mixed_valence', 'Inorganic Chemistry', 'Mixed‑valence complexes and oxidation states', '["chem_12_coordination_chemistry","chem_12_electronic_spectra"]', '["mixed valence","oxidation state","magnetic moment","intervalence charge transfer","electron transfer"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 3, -2.0, 'Consider the complex [Fe₂(SO₄)₃]·xH₂O, which contains iron in two different oxidation states (mixed‑valence). Which of the following statements are always true for such mixed‑valence complexes? (Select all that apply.)', '["The overall charge of the complex can be determined by summing the individual oxidation states of the metal ions.", "The presence of mixed oxidation states always leads to intervalence charge‑transfer bands in the visible spectrum.", "The magnetic moment of the complex is the vector sum of the moments of the individual iron ions.", "The complex can exhibit both inner‑sphere and outer‑sphere electron transfer pathways."]', '["THE OVERALL CHARGE OF THE COMPLEX CAN BE DETERMINED BY SUMMING THE INDIVIDUAL OXIDATION STATES OF THE METAL IONS.", "THE MAGNETIC MOMENT OF THE COMPLEX IS THE VECTOR SUM OF THE MOMENTS OF THE INDIVIDUAL IRON IONS."]', 'For any complex, the net charge equals the sum of the oxidation numbers of all constituent atoms (statement 1). Magnetic moments add vectorially because each metal ion contributes its own spin and orbital contributions (statement 3). Intervalence charge‑transfer bands appear only in certain electronic configurations, not universally (statement 2). Electron‑transfer pathways depend on the specific ligand environment, not a guaranteed feature (statement 4).', '["Step 1: Apply the oxidation‑state bookkeeping rule to obtain the overall charge.", "Step 2: Recognize that magnetic moments of individual ions combine vectorially.", "Step 3: Evaluate the universality of spectroscopic and kinetic statements."]', 'Overall charge = Σ (oxidation state × number of atoms) for all constituents.', 'chem.inorg.mixed_valence_properties', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:00:38.951Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cafdabad4cfdeb2a8ee1c65d8d1897f1', 'NEET', '12', 'Biology', 'bio_12_neet_human_reproduction', 'Human Reproduction', 'Gametogenesis comparison male female', '[]', '["Gametogenesis","Gametes","Reproductive organs"]', 0, 0, '[]', 'MCQ', NULL, 0, 1700, 'NEET_EASY', 3, -1.0, 'Gametogenesis is the process by which gametes are produced in the reproductive organs of an organism.', '["Gametogenesis is the process by which gametes are produced in the reproductive organs of an organism.", "Gametogenesis is the process by which gametes are produced in the somatic cells of an organism.", "Gametogenesis is the process by which gametes are produced in the germ cells of an organism.", "Gametogenesis is the process by which gametes are produced in the embryonic cells of an organism."]', 'Gametogenesis is the process by which gametes are produced in the reproductive organs of an organism.', 'Step 1: Recall the definition of gametogenesis. Step 2: Identify the correct location where gametes are produced. Step 3: Verify that the correct answer matches the given definition.', '["Step 1: Recall the definition of gametogenesis.", "Step 2: Identify the correct location where gametes are produced.", "Step 3: Verify that the correct answer matches the given definition."]', '', 'biology.human_reproduction.gametogenesis_comparison_male_female', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:40:04.361Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cafdc2c680df9fac83e9510298850c95', 'Board', '10', 'Science', 'sci_10_board_tropisms', 'Control and Coordination', 'Tropisms', '[]', '["phototropism","geotropism","auxin redistribution","plant hormones","growth response"]', 0, 0, '[]', 'MCQ', NULL, 0, 1180, 'BOARD_EASY', 2, 0.0, 'The growth response of a plant stem towards light is called ______, while the growth response of roots towards gravity is called ______.', '["Phototropism and Geotropism", "Geotropism and Phototropism", "Thigmotropism and Hydrotropism", "Hydrotropism and Thigmotropism"]', 'Phototropism and Geotropism', 'Phototropism refers to growth towards light, and geotropism (or gravitropism) refers to growth in response to gravity, typically seen in roots. The first option correctly pairs the two terms.', '["Step 1: Recall that stem bending towards light is phototropism.", "Step 2: Recall that root growth direction governed by gravity is geotropism.", "Step 3: Match the definitions with the correct terms."]', '', 'science.control.tropism_names', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:29:59.920Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('cafebb43056870a7d7fdfaa3d77c299d', 'Board', '10', 'Science', 'sci_10_life_osmoregulation', 'Life Processes', 'Osmoregulation', '[]', '["osmotic pressure","van''t Hoff factor","temperature effect","solute concentration","R constant"]', 0, 0, '[]', 'MCQ', NULL, 0, 1250, 'BOARD_EASY', 3, 0.0, 'The osmotic pressure $\pi$ of a 0.250 M glucose solution at $25^{\circ}\text{C}$ (298 K) is closest to:', '["$6.1\\ \\text{atm}$", "$12.2\\ \\text{atm}$", "$3.1\\ \\text{atm}$", "$0.5\\ \\text{atm}$"]', '$6.1\ \text{atm}$', 'Use the van''t Hoff equation $\pi = iMRT$ (glucose is non‑electrolyte, $i=1$). Substitute $M=0.250\,\text{mol L}^{-1}$, $R=0.0821\,\text{L·atm·K}^{-1}\text{mol}^{-1}$ and $T=298\,\text{K}$ to obtain $\pi \approx 6.1\,\text{atm}$. The other options arise from common arithmetic or unit‑conversion errors.', '["Step 1: Write the formula $\\pi = iMRT$.", "Step 2: Insert the values $i=1$, $M=0.250$, $R=0.0821$, $T=298$.", "Step 3: Compute $\\pi = 1 \\times 0.250 \\times 0.0821 \\times 298 \\approx 6.1\\,\\text{atm}$."]', '$\pi = iMRT$', 'science.life_processes.osmotic_pressure_calculation', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:39:08.249Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('caff88f6e59bad7d60d296225e63b7db', 'JEEMains', '12', 'Mathematics', 'math_12_jm_diff_eq', 'Differential Equations', 'Bernoulli equation', '[]', '["Bernoulli equation","nonlinear ODE","substitution method","linear differential equation","integrating factor"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'The differential equation $ \frac{dy}{dx} + y = y^3 e^x $ is reduced to linear form by substituting:', '["$ v = y^{-2} $", "$ v = y^2 $", "$ v = \\frac{1}{y} $", "$ v = \\ln y $"]', '$ v = y^{-2} $', 'Bernoulli equation with $ n=3 $, use $ v = y^{1-3} = y^{-2} $.', '["Step 1: Standard Bernoulli: $ y'' + Py = Qy^n $", "Step 2: Here $ n=3 $, so $ v = y^{1-n} = y^{-2} $", "Step 3: Transform to linear in $ v $"]', 'v = y^{1-n}', 'math.diff_eq.bernoulli_substitution', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:19:16.585Z', 1);
